            id: n.id || uid("pl-"),
            type: n.type || "scene",
            title: n.title || "\u0E44\u0E21\u0E48\u0E23\u0E30\u0E1A\u0E38\u0E0A\u0E37\u0E48\u0E2D",
            color: n.color || "#3f3e3a",
            x: Number(n.x) || 0,
            y: Number(n.y) || 0,
            width: Number(n.width) || CARD_W,
            height: Number(n.height) || CARD_H,
            file: n.file || null,
            tags: Array.isArray(n.tags) ? n.tags : [],
            synopsis: n.synopsis || "",
