          const label = new import_fabric.fabric.Text("\u{1F5C2} " + g.name, {
            left: g.x + 10,
            top: g.y + 8,
            fontSize: 12,
            fill: g.color,
            fontFamily: '"Segoe UI", sans-serif',
            selectable: false,
            evented: false
          });
          label.kind = "grouplabel";
          label.gid = g.id;
          this.canvas.add(rect);
          this.canvas.add(label);
          this.canvas.sendToBack(label);
