          const w = (vis.width || CARD_W) / 2, h = (vis.height || CARD_H) / 2;
          const dx = towards.x - c.x, dy = towards.y - c.y;
          if (!dx && !dy) return c;
          const sx = dx ? w / Math.abs(dx) : Infinity;
