  async function openConsistencyCheck(entityPath) {
    if (!await aiReady2()) return;
    if (!entityPath) {
      setStatus("\u0E40\u0E25\u0E37\u0E2D\u0E01\u0E40\u0E2D\u0E19\u0E17\u0E34\u0E15\u0E35\u0E49 (\u0E15\u0E31\u0E27\u0E25\u0E30\u0E04\u0E23) \u0E01\u0E48\u0E2D\u0E19");
      return;
    }
    let entity;
    try {
      entity = await kapi.readJson(entityPath);
    } catch {
      setStatus("\u0E2D\u0E48\u0E32\u0E19\u0E44\u0E1F\u0E25\u0E4C\u0E40\u0E2D\u0E19\u0E17\u0E34\u0E15\u0E35\u0E49\u0E44\u0E21\u0E48\u0E2A\u0E33\u0E40\u0E23\u0E47\u0E08");
      return;
    }
    if (!entity || !entity.name) {
      setStatus("\u0E40\u0E2D\u0E19\u0E17\u0E34\u0E15\u0E35\u0E49\u0E44\u0E21\u0E48\u0E21\u0E35\u0E0A\u0E37\u0E48\u0E2D");
      return;
    }
    setStatus("\u{1F3AD} \u0E01\u0E33\u0E25\u0E31\u0E07\u0E15\u0E23\u0E27\u0E08\u0E2A\u0E2D\u0E1A\u0E04\u0E27\u0E32\u0E21\u0E2A\u0E21\u0E48\u0E33\u0E40\u0E2A\u0E21\u0E2D\u2026");
    showDialog("\u{1F3AD} \u0E15\u0E23\u0E27\u0E08\u0E2A\u0E2D\u0E1A\u0E04\u0E27\u0E32\u0E21\u0E2A\u0E21\u0E48\u0E33\u0E40\u0E2A\u0E21\u0E2D \u2014 " + entity.name, async (box, ov) => {
      const resultDiv = el("div");
      resultDiv.style.cssText = "max-height:50vh;overflow-y:auto;white-space:pre-wrap;font-size:14px;line-height:1.8;min-height:80px";
      resultDiv.textContent = "\u0E01\u0E33\u0E25\u0E31\u0E07\u0E23\u0E27\u0E1A\u0E23\u0E27\u0E21\u0E02\u0E49\u0E2D\u0E21\u0E39\u0E25\u2026";
      box.append(resultDiv);
      const scenes = (await listScenes(state.root, { withText: true })).map((s) => ({ id: s.id, title: s.title, text: s.text || "", storyDate: s.row.storyDate || "" }));
      resultDiv.textContent = "\u0E01\u0E33\u0E25\u0E31\u0E07\u0E2A\u0E48\u0E07\u0E43\u0E2B\u0E49 AI \u0E27\u0E34\u0E40\u0E04\u0E23\u0E32\u0E30\u0E2B\u0E4C\u2026";
      const { checkConsistency: checkConsistency2 } = await Promise.resolve().then(() => (init_ai_character(), ai_character_exports));
      const { getAIClient: getAIClient2 } = await Promise.resolve().then(() => (init_ai_bridge(), ai_bridge_exports));
      const res = await checkConsistency2(entityPath, { client: getAIClient2(), entity, scenes });
      resultDiv.textContent = "";
      if (!res.issues.length) {
        resultDiv.textContent = res.error ? "\u274C " + res.error : "\u2705 \u0E44\u0E21\u0E48\u0E1E\u0E1A\u0E04\u0E27\u0E32\u0E21\u0E44\u0E21\u0E48\u0E2A\u0E21\u0E48\u0E33\u0E40\u0E2A\u0E21\u0E2D";
      } else {
        resultDiv.append(el("div", "dim", `\u0E1E\u0E1A ${res.issues.length} \u0E08\u0E38\u0E14 \u0E08\u0E32\u0E01 ${res.appearances || 0} \u0E09\u0E32\u0E01\u0E17\u0E35\u0E48\u0E1B\u0E23\u0E32\u0E01\u0E0F`));
        for (const it of res.issues) {
          const row = el("div");
          row.style.cssText = "margin:8px 0;padding:8px 10px;background:var(--side);border-radius:6px;border-left:3px solid var(--accent)";
          row.append(el("div", "", `\u2022 [${it.aspect || "\u0E17\u0E31\u0E48\u0E27\u0E44\u0E1B"}] ${it.issue || ""}`));
          if (it.sceneTitle || it.sceneId) row.append(el("div", "dim", "\u0E09\u0E32\u0E01: " + (it.sceneTitle || it.sceneId)));
          if (it.evidence) row.append(el("div", "dim", "\u0E2B\u0E25\u0E31\u0E01\u0E10\u0E32\u0E19: " + it.evidence));
          if (it.suggestion) row.append(el("div", "", "\u{1F4A1} " + it.suggestion));
          resultDiv.append(row);
        }
      }
      const btns = el("div", "k-dlg-btns");
      const closeBtn = el("button", "k-cancel", "\u0E1B\u0E34\u0E14");
      closeBtn.onclick = () => ov.remove();
      btns.append(closeBtn);
      box.append(btns);
    });
  }
