    mgrBtn.onclick = () => openBookManager();
    addSecRow.append(mgrBtn);
    const tlBtn = el("div", "scene add-row", "\u{1F552} \u0E40\u0E2A\u0E49\u0E19\u0E40\u0E27\u0E25\u0E32\u2026");
