  async function openSnapshotRight(curFile, snap) {
    const key = "::snap::" + snap.path;
    const title = "\u{1F558} " + (snap.label || fmtTs(snap.ts));
    if (!state.tabs.has(key)) {
      let body = "";
      try {
        body = (0, import_md10.parseMdFile)(await kapi.readFile(snap.path)).body;
      } catch {
        body = "(\u0E2D\u0E48\u0E32\u0E19\u0E44\u0E1F\u0E25\u0E4C\u0E40\u0E27\u0E2D\u0E23\u0E4C\u0E0A\u0E31\u0E19\u0E44\u0E21\u0E48\u0E44\u0E14\u0E49)";
      }
      const pane = el("div", "pane");
      const bar = el("div", "json-bar");
      bar.append(el("span", "dim", title + " \u2014 \u0E2D\u0E48\u0E32\u0E19\u0E2D\u0E22\u0E48\u0E32\u0E07\u0E40\u0E14\u0E35\u0E22\u0E27"));
      const ta = el("textarea", "plain-md");
      ta.value = body;
      ta.readOnly = true;
      pane.append(bar, ta);
      $("#panes").append(pane);
      const tabBtn = el("div", "tab");
      tabBtn.append(el("span", "tab-title", title));
      const x = el("span", "tab-x", "\xD7");
      tabBtn.append(x);
      $("#tabs").append(tabBtn);
      const tab = {
        file: key,
        title,
        pane,
        tabBtn,
        dirty: false,
        editor: null,
        plain: null,
        wiki: null,
        isJson: true,
        readOnly: true,
        save: async () => true
      };
      tabBtn.onclick = (e) => {
        if (e.target !== x) activate(key);
      };
      x.onclick = () => closeTab(key);
      state.tabs.set(key, tab);
    }
    if (curFile && state.tabs.has(curFile)) activate(curFile);
    applyCompare(key);
    return key;
  }
