  function refreshOutline() {
    const box = $("#outline");
    box.innerHTML = "";
    const t2 = state.active;
    if (!t2 || t2.wiki || t2.gal || t2.isJson || t2.net || t2.dash || t2.planner || !t2.editor && !t2.sp && !t2.plain) {
      box.append(el("div", "dim", "(\u0E40\u0E1B\u0E34\u0E14\u0E09\u0E32\u0E01\u0E40\u0E1E\u0E37\u0E48\u0E2D\u0E14\u0E39 Navigation)"));
      return;
    }
    const head = el("div", "nav-head");
    head.append(el("span", "nav-scene", (t2.sp ? "\u{1F3AC} " : "\u{1F4D6} ") + (t2.title || "(\u0E09\u0E32\u0E01)")));
    box.append(head);
    const items = [];
    if (t2.editor) {
      t2.editor.view.state.doc.forEach((n, offset) => {
        if (n.type.name === "heading")
          items.push({ kind: "heading", label: n.textContent || "(\u0E27\u0E48\u0E32\u0E07)", lvl: n.attrs.level, pos: offset });
        else if (navShowBeats && n.type.name === "paragraph" && n.textContent.trim())
          items.push({ kind: "beat", label: navTrunc(n.textContent), lvl: 4, pos: offset });
        else if (navShowBeats && n.type.name === "blockquote" && n.textContent.trim())
          items.push({ kind: "quote", label: navTrunc(n.textContent), lvl: 4, pos: offset });
      });
    } else if (t2.sp) {
      const MAP = {
        scene: ["sceneHeading", 2],
        outline1: ["outline", 1],
        outline2: ["outline", 2],
        outline3: ["outline", 3],
        character: ["character", 3],
        transition: ["transition", 3],
        summary: ["summary", 4]
      };
      t2.sp.view.state.doc.forEach((n, offset) => {
        const hit = MAP[n.attrs.el];
        if (!hit) return;
        if (hit[0] === "character" && !navShowBeats) return;
        if (n.textContent.trim()) items.push({ kind: hit[0], label: n.textContent, lvl: hit[1], pos: offset });
      });
    } else {
      t2.plain.value.split("\n").forEach((line, i2) => {
        const m = /^(#{1,6})\s+(.*)$/.exec(line);
        if (m) items.push({ kind: "heading", label: m[2], lvl: m[1].length, line: i2 });
        else if (/^\.[^.]/.test(line.trim()) || /^(INT|EXT)[.\s]/i.test(line.trim()))
          items.push({ kind: "sceneHeading", label: line.trim().replace(/^\./, ""), lvl: 2, line: i2 });
        else if (navShowBeats && line.trim())
          items.push({ kind: "beat", label: navTrunc(line), lvl: 4, line: i2 });
      });
    }
    if (!items.length) {
      box.append(el("div", "dim", "(\u0E22\u0E31\u0E07\u0E44\u0E21\u0E48\u0E21\u0E35\u0E2B\u0E31\u0E27\u0E02\u0E49\u0E2D/\u0E2B\u0E31\u0E27\u0E09\u0E32\u0E01)"));
      return;
    }
    for (const it of items) {
      const d = el("div", "ol-item nav-" + it.kind + " lvl" + it.lvl, it.label || "(\u0E27\u0E48\u0E32\u0E07)");
      d.onclick = () => {
        if (t2.sp || t2.editor) {
          const view = (t2.sp || t2.editor).view;
          Promise.resolve().then(() => (init_dist4(), dist_exports)).then(({ TextSelection: TextSelection2 }) => {
            view.dispatch(view.state.tr.setSelection(
              TextSelection2.create(view.state.doc, it.pos + 1)
            ).scrollIntoView());
            view.focus();
          });
        } else {
          const lines = t2.plain.value.split("\n");
          let off = 0;
          for (let i2 = 0; i2 < it.line; i2++) off += lines[i2].length + 1;
          t2.plain.focus();
          t2.plain.setSelectionRange(off, off);
        }
      };
      box.append(d);
    }
  }
