  function makeDraggable(elm, handle, opts = {}) {
    const { key, defaultPos } = opts;
    const saved = key ? uiLayout()[key] : null;
    const pos = saved || defaultPos;
    if (pos) {
      elm.style.left = pos.left + "px";
      elm.style.top = pos.top + "px";
      elm.style.right = "auto";
      elm.style.bottom = "auto";
      if (opts.resizable && pos.width) {
        elm.style.width = pos.width + "px";
        elm.style.height = pos.height + "px";
      }
    }
    if (saved && saved.hidden) elm.style.display = "none";
    let sx, sy, ox, oy, dragging = false, lastE = null;
    const down = (e) => {
      if (e.button !== 0 || !elm) return;
      dragging = true;
      sx = e.clientX;
      sy = e.clientY;
      const r = elm.getBoundingClientRect();
      const op = elm.offsetParent;
      const host2 = op ? op.getBoundingClientRect() : { left: 0, top: 0 };
      ox = r.left - host2.left;
      oy = r.top - host2.top;
      elm.classList.add("k-dragging");
      document.addEventListener("mousemove", move);
      document.addEventListener("mouseup", up);
      e.preventDefault();
    };
    const move = (e) => {
      if (!dragging) return;
      lastE = e;
      const op = elm.offsetParent;
      const host2 = op ? op.getBoundingClientRect() : { left: 0, top: 0, width: innerWidth, height: innerHeight };
      let nx = ox + (e.clientX - sx), ny = oy + (e.clientY - sy);
      nx = Math.max(0, Math.min(nx, host2.width - 40));
      ny = Math.max(0, Math.min(ny, host2.height - 24));
      if (opts.snap) {
        const SNAP = 9;
        const r = elm.getBoundingClientRect();
        const targets = [...document.querySelectorAll(".k-float-panel, .float-win")].filter((p) => p !== elm).map((p) => p.getBoundingClientRect());
        targets.push({ left: 0, top: 0, right: innerWidth, bottom: innerHeight });
        for (const t2 of targets) {
          if (Math.abs(nx - t2.left) < SNAP) nx = t2.left;
          if (Math.abs(nx + r.width - t2.right) < SNAP) nx = t2.right - r.width;
          if (Math.abs(nx - t2.right) < SNAP) nx = t2.right;
          if (Math.abs(ny - t2.top) < SNAP) ny = t2.top;
          if (Math.abs(ny + r.height - t2.bottom) < SNAP) ny = t2.bottom - r.height;
          if (Math.abs(ny - t2.bottom) < SNAP) ny = t2.bottom;
        }
      }
      elm.style.left = nx + "px";
      elm.style.top = ny + "px";
      elm.style.right = "auto";
      elm.style.bottom = "auto";
      opts.onMove && opts.onMove(e);
    };
    const up = () => {
      dragging = false;
      elm.classList.remove("k-dragging");
      document.removeEventListener("mousemove", move);
      document.removeEventListener("mouseup", up);
      if (key) saveUiLayout(key, {
        left: parseInt(elm.style.left, 10) || 0,
        top: parseInt(elm.style.top, 10) || 0
      });
      opts.onEnd && opts.onEnd(lastE);
    };
    handle.addEventListener("mousedown", down);
    return {
      reset() {
        if (key) {
          const l = uiLayout();
          delete l[key];
          localStorage.setItem("k2-ui-layout", JSON.stringify(l));
        }
        if (defaultPos) {
          elm.style.left = defaultPos.left + "px";
          elm.style.top = defaultPos.top + "px";
        }
      }
    };
  }
